                    import com.inticube.xcron.resource.JDBCDataSource;
                    import com.inticube.xcron.resource.DataSourceManager;
                    import com.inticube.xcron.logs.Logger;

                    try {
                    	JDBCDataSource ds1 = (JDBCDataSource)DataSourceManager.getInstance().getDataSource("msensdatasource");
						JDBCDataSource ds2 = (JDBCDataSource)DataSourceManager.getInstance().getDataSource("snmpdatasource");
						JDBCDataSource ds3 = (JDBCDataSource)DataSourceManager.getInstance().getDataSource("tmdatasource");

						try {
							ds1.createConnectionPool();
							ds2.createConnectionPool();
							ds3.createConnectionPool();						
						} catch (Exception e) {
							Logger.error("********XCronAppException");
						}

                    } catch (Exception e) {
						Logger.error("********XCronAppException");
					}


import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.URLConnection;
import com.inticube.xcron.logs.Logger;
import java.net.InetAddress;

try {
	String serverIp = InetAddress.getLocalHost().getHostAddress();
	//String sUrl = "http://10.48.241.41:8080/msens/cs.com.codeutil.refresh.do?cmd=refresh";

	String sUrl = "http://"+serverIp+":8080/msens/cs.com.codeutil.refresh.do?cmd=refresh";

	URL url = new URL(sUrl);
	URLConnection urlConnection = url.openConnection();

	BufferedReader in = new BufferedReader(new InputStreamReader(urlConnection.getInputStream()));

	String inputLine = "";

	while ((inputLine = in.readLine()) != null) { 
		System.out.println(inputLine);
	}

	in.close();
} catch(Exception e) {
	Logger.error(e.getMessage(), e);
}


